        self._grade_points = grade_points
    def get_grade_points(self):
        return self._grade_points

class University:
    def __init__(self, enrollments_dict, courses_dict):
        # enrollments_dict: { student_id : [Enrollment, ...] }
        # courses_dict: { course_code : Course }
        self.enrollments_dict = enrollments_dict
        self.courses_dict = courses_dict

    def get_student_enrollments(self, student_id):
