# We'll patch calculate_simple_gpa to take (university, student_id) as arguments
def calculate_simple_gpa(university, student_id):
    '''
    Create a function called calculate_simple_gpa that takes a University object and student_id.
    For each enrollment from university.get_student_enrollments(student_id), get the course using university.get_course(enrollment.course_code),
    multiply enrollment.get_grade_points() by course.credits, sum all points and credits,
    return total_points / total_credits as GPA (0.0-4.0).
    '''
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0.0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is not None and course.credits > 0:
            points = enrollment.get_grade_points() * course.credits
            total_points += points
            total_credits += course.credits
    if total_credits == 0:
        return 0.0
    return total_points / total_credits

