    - summary: returns dict with employee_id, overall_rating (float), goals_status
    - detailed: returns dict of all CSV columns with correct types
    - department (when employee_id is None): {department: {'avg_rating': ..., 'count': ...}, ...}
    '''
    # Helper function to convert types for a row
    def parse_row(row: dict) -> dict:
        # Columns that should be int/float
        float_fields = [
            'technical_score', 'communication_score', 'teamwork_score',
            'leadership_score', 'overall_rating'
        ]
        int_fields = [
            'technical_score', 'communication_score', 'teamwork_score',
            'leadership_score'
        ]
        new_row = {}
        for key, value in row.items():
            if key in float_fields:
                try:
                    new_row[key] = float(value)
                except Exception:
                    new_row[key] = value
            else:
                new_row[key] = value
        # maintain overall_rating as float
        if 'overall_rating' in row:
            new_row['overall_rating'] = float(row['overall_rating'])
        return new_row

    # Load CSV rows
    csv_rows = []
