from typing import Optional, Dict, Any

def performance_report(employee_id: Optional[str] = None, report_type: str = 'summary') -> Dict[str, Any]:
    '''
    Reads the performance_reviews.csv and provides performance reporting.

    Parameters:
        - employee_id: Optional; string or None
        - report_type: 'summary', 'detailed', or 'department' (default 'summary')

    Returns:
        - summary: dict with keys 'employee_id' (str), 'overall_rating' (float), 'goals_status' (str)
        - detailed: dict with all original columns; types preserved (numbers as int/float, rest as str)
        - department: dict of { department: { 'avg_rating': float, 'count': int } }
    '''
    # Helper: Cast a single field
    def parse_value(key, val):
        # These are the fields that should be loaded as float
        float_cols = {'overall_rating'}
        int_cols = {
            'technical_score', 'communication_score', 'teamwork_score', 'leadership_score'
        }
        if key in float_cols and val:
            try:
                return float(val)
            except ValueError:
                return None
        elif key in int_cols and val:
            try:
                return int(val)
            except ValueError:
                return None
        else:
            return val

    # Load CSV with preserved column names and type conversion
    rows = []
    with open('performance_reviews.csv', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for r in reader:
            row = {k: parse_value(k, v) for k, v in r.items()}
            rows.append(row)

    # summary/detailed mode: find row for employee_id
    if employee_id:
        target = None
        for r in rows:
            if r['employee_id'] == employee_id:
                target = r
                break
        if not target:
            raise ValueError(f"employee_id '{employee_id}' not found.")

        if report_type == 'summary':
            return {
                'employee_id': target['employee_id'],
                'overall_rating': target['overall_rating'],
                'goals_status': target['goals_status'],
            }
        elif report_type == 'detailed':
            return target
        else:
            raise ValueError(f"Unknown report_type '{report_type}'.")

    # department mode: group by department
    elif report_type == 'department':
        dept_stats = {}
        for r in rows:
            dept = r['department']
            rating = r['overall_rating']
            if dept not in dept_stats:
                dept_stats[dept] = {'ratings': [], 'count': 0}
            if rating is not None:
                dept_stats[dept]['ratings'].append(rating)
            dept_stats[dept]['count'] += 1
        result = {}
        for dept, stats in dept_stats.items():
            ratings = stats['ratings']
            count = stats['count']
            avg = float(sum(ratings))/len(ratings) if ratings else 0.0
            result[dept] = {'avg_rating': round(avg, 2), 'count': count}
        return result
    else:
        raise ValueError("Invalid mode or insufficient parameters.")


