    '''
    # Step 1: Load the CSV data
    filename = 'performance_reviews.csv'
    rows = []
    # List of columns that should be converted to float
    float_cols = ['technical_score', 'communication_score', 'teamwork_score', 'leadership_score', 'overall_rating']
    int_cols = []

    # Load and typecast CSV rows
    with open(filename, newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            # Typecast numeric fields
            for col in float_cols:
                if col in row:
                    try:
                        row[col] = float(row[col])
                    except ValueError:
                        row[col] = None
            rows.append(row)

    if report_type in ('summary', 'detailed'):
